// ---------------------------------------------------------------------------
// Public component
// ---------------------------------------------------------------------------
export function LiveLineChart({ data, value, dataKey = "value", window: windowSecs = 30, numXTicks = 5, nowOffsetUnits = 0, exaggerate = false, lerpSpeed = LERP_SPEED, margin: marginProp, paused = false, children, className, style, }: LiveLineChartProps) {
