export function LiveLine({ dataKey, stroke = chartCssVars.linePrimary, strokeWidth = 2, curve = curveMonotoneX, fill = true, pulse = true, dotSize = 4, badge = true, formatValue = (v: number) => v.toFixed(2), momentumColors, }: LiveLineProps) {
