          <stop offset="100%" stopColor={resolvedStroke} stopOpacity={0.6}/>
        </linearGradient>
        <linearGradient id={areaGradientId} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0%" stopColor={resolvedStroke} stopOpacity={0.1}/>
          <stop offset="100%" stopColor={resolvedStroke} stopOpacity={0}/>
        </linearGradient>
        <linearGradient id={fadeId} x1="0" x2="1" y1="0" y2="0">
          <stop offset="0%" style={{ stopColor: "white", stopOpacity: 0 }}/>
          <stop offset="4%" style={{ stopColor: "white", stopOpacity: 1 }}/>
          {liveDotX < innerWidth - 1 ? (<>
              <stop offset={`${(liveDotX / innerWidth) * 100}%`} style={{ stopColor: "white", stopOpacity: 1 }}/>
              <stop offset="100%" style={{ stopColor: "white", stopOpacity: 0 }}/>
            </>) : (<stop offset="100%" style={{ stopColor: "white", stopOpacity: 1 }}/>)}
        </linearGradient>
        <mask id={fadeMaskId}>
          <rect fill={`url(#${fadeId})`} height={innerHeight + 40} width={innerWidth} x={0} y={-20}/>
        </mask>
      </defs>

      {/* Area fill */}
