          <AreaClosed curve={curve} data={data} fill={`url(#${areaGradientId})`} strokeWidth={0} x={getX} y={getY} yScale={yScale}/>
        </g>)}

      {/* Line */}
      {data.length > 1 && (<g mask={`url(#${fadeMaskId})`}>
          <LinePath curve={curve} data={data} stroke={`url(#${gradientId})`} strokeLinecap="round" strokeLinejoin="round" strokeWidth={strokeWidth} x={getX} y={getY}/>
        </g>)}

