          {pulse && (<circle cx={liveDotX} cy={liveDotY} fill="none" opacity={0.4} r={dotSize * 2} stroke={dotColor} strokeWidth={1.5}>
              <animate attributeName="r" dur="1.5s" from={String(dotSize)} repeatCount="indefinite" to={String(dotSize * 3.5)}/>
              <animate attributeName="opacity" dur="1.5s" from="0.5" repeatCount="indefinite" to="0"/>
            </circle>)}
