            <rect fill="var(--surface-floating)" height={24} opacity={0.95} rx={6} width={formatValue(liveValue).length * 7.5 + 16} x={0} y={-12}/>
            <text fill="var(--fg-default)" fontFamily="SF Mono, Menlo, Monaco, monospace" fontSize={11} fontWeight={500} x={8} y={4}>
              {formatValue(liveValue)}
            </text>
          </g>)}
      </motion.g>
    </>);
}
export default LiveLine;

